<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class ArtistPortalWeb {
 public const VIEWS=['membership'=>'عضویت هنری','profile'=>'پروفایل هنری من','works'=>'آثار من','archive'=>'انتخاب آثار از آرشیو','claims'=>'درخواست‌های انتساب من','send'=>'ارسال اثر جدید','sent'=>'آثار ارسالی من','calls'=>'فراخوان‌ها'];
 public static function handles(string $a):bool{return in_array($a,['artist-apply','artist-profile-save','artist-select','artist-clear','artist-claim-submit','artist-work-submit','artist-join-review','artist-claim-review','artist-admin-assign','artist-work-review','artist-martyr-resolve','artist-martyr-create'],true);}
 private static function source(string $name):?string {$files=Web::files($name);if(count($files)>1)throw new HttpError(422,'فقط یک فایل انتخاب کنید.');if(!$files)return null;if(!preg_match('/\.(jpe?g|png|webp)$/iD',$files[0]['name']))throw new HttpError(422,'فرمت JPG، JPEG، PNG یا WebP انتخاب کنید.');return Upload::receive($files[0]);}
 private static function json(array $data):never {header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');echo json_encode(['ok'=>true]+$data,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG);exit;}
 public static function action(PDO $db,string $a):never {
  $actor=Security::user($db);if(!$actor)throw new HttpError(403,'ابتدا وارد حساب شوید.');ArtistPortalSchema::requireReady($db);$id=(int)($_POST['id']??0);$back='account';$params=['section'=>'artist','view'=>'membership'];
  try {switch($a){
   case 'artist-apply':$samples=[];foreach(Web::files('samples') as $f){if(!preg_match('/\.(jpe?g|png|webp)$/iD',$f['name']))throw new HttpError(422,'نمونه‌کار باید تصویر معتبر باشد.');$samples[]=Upload::receive($f);}ArtistMemberships::apply($db,$actor,$_POST,self::source('avatar'),$samples);break;
   case 'artist-profile-save':$params['view']='profile';ArtistMemberships::saveProfile($db,$actor,$_POST,self::source('avatar'));break;
   case 'artist-select':Security::limit($db,'artist-select',150,60);self::json(['selected'=>ArtistClaims::select($db,$actor,$id,($_POST['selected']??'')==='1')]);
   case 'artist-clear':$params['view']='archive';ArtistClaims::clear($db,$actor);break;
   case 'artist-claim-submit':$params['view']='claims';ArtistClaims::request($db,$actor);break;
   case 'artist-work-submit':$params['view']='send';if($id)$params['id']=$id;$sid=ArtistWorks::submit($db,$actor,$_POST,self::source('artwork'),$id,self::source('previews'));Web::uploadResponse('account',['section'=>'artist','view'=>'sent','id'=>$sid]);
   case 'artist-join-review':$back='admin';$params=['tab'=>'artist-joins','edit'=>$id];ArtistMemberships::review($db,$actor,$id,$_POST);break;
   case 'artist-claim-review':$back='admin';$params=['tab'=>'artist-claims'];$decisions=$_POST['decisions']??[];if(!is_array($decisions))throw new HttpError(422,'تصمیم‌ها معتبر نیستند.');$chosen=$_POST['chosen']??[];if(!is_array($chosen)||count($chosen)>200)throw new HttpError(422,'انتخاب‌ها معتبر نیستند.');$final=[];foreach($chosen as $key){if(!is_scalar($key)||!isset($decisions[$key]))throw new HttpError(422,'شناسه درخواست معتبر نیست.');$final[$key]=$decisions[$key];if(($_POST['bulk_status']??'')!=='')$final[$key]['status']=$_POST['bulk_status'];if(($final[$key]['note']??'')===''&&($_POST['bulk_note']??'')!=='')$final[$key]['note']=$_POST['bulk_note'];}ArtistClaims::review($db,$actor,$final);break;
   case 'artist-admin-assign':$back='admin';$params=['tab'=>'artist-claims'];$ids=preg_split('/[\s,،]+/u',Security::normalize(Security::text($_POST,'image_ids',3000)),-1,PREG_SPLIT_NO_EMPTY);foreach($ids as $v)if(!ctype_digit($v))throw new HttpError(422,'کد تصاویر را با فاصله یا ویرگول جدا کنید.');ArtistClaims::assign($db,$actor,(int)($_POST['artist_id']??0),$ids,Security::text($_POST,'note',5000));break;
   case 'artist-work-review':$back='admin';$params=['tab'=>'artist-works','edit'=>$id];ArtistWorks::review($db,$actor,$id,$_POST,self::source('verified_preview'));break;
   case 'artist-martyr-resolve':case 'artist-martyr-create':$back='admin';$params=['tab'=>'artist-martyrs','edit'=>$id];ArtistWorks::resolve($db,$actor,$id,$_POST,$a==='artist-martyr-create');break;
  }unset($_SESSION['artist_old']);$_SESSION['flash']='اطلاعات ثبت شد.';redirect($back,$params);
  }catch(HttpError|ProtocolErrors $e){if(str_contains($_SERVER['HTTP_ACCEPT']??'','application/json'))throw $e;$_SESSION['artist_old']=$_POST;unset($_SESSION['artist_old']['csrf']);$_SESSION['flash']=$e->getMessage();$_SESSION['flash_type']='error';redirect($back,$params);}
 }
 public static function account(PDO $db,array $user,array $sections):void {
  ArtistPortalSchema::requireReady($db);$membership=ArtistMemberships::get($db,(int)$user['id']);$artistId=ArtistMemberships::approved($db,(int)$user['id']);$mode=Security::text($_GET,'view',30,false)?:($artistId?'works':'membership');if(!isset(self::VIEWS[$mode]))throw new HttpError(404,'بخش هنری پیدا نشد.');if($mode!=='membership')ArtistMemberships::requireArtist($db,$user);
  $old=$_SESSION['artist_old']??[];unset($_SESSION['artist_old']);$data=compact('db','user','sections','membership','artistId','mode','old')+['artist'=>null,'entry'=>null];
  $data['terms']=Db::query($db,"SELECT * FROM protocol_terms WHERE taxonomy IN ('art_specialty','media_type') AND active=1 ORDER BY taxonomy,sort_order,title")->fetchAll();if($artistId)$data['artist']=(new Artists($db,$user))->get($artistId);
  $id=(int)($_GET['id']??0);if(in_array($mode,['send','sent'],true)&&$id){$data['entry']=ArtistWorks::get($db,$user,$id);if((int)$data['entry']['user_id']!==(int)$user['id'])throw new HttpError(404,'اثر شما پیدا نشد.');if($mode==='send'&&$data['entry']['status']!=='needs_changes')throw new HttpError(409,'اثر تنها پس از درخواست اصلاح قابل ویرایش است.');}
  if($mode==='works')$data['result']=(new Archive($db))->images(['artist_id'=>$artistId,'kind'=>'all'],max(1,(int)($_GET['p']??1)));
  if($mode==='claims')$data['result']=AdminQueries::paginate($db,'SELECT c.*,i.title','FROM artist_work_claims c JOIN images i ON i.id=c.image_id','c.user_id=?',[$user['id']],['new'=>'c.id DESC'],$_GET);
  if($mode==='sent')$data['result']=self::worksList($db,$user,$_GET,true);
  if($mode==='archive'){$data['f']=GalleryFacets::input($db,$_GET);$data['catalogFilters']=GalleryFacets::options($db,$data['f']);$data['result']=(new Archive($db))->images($data['f'],max(1,(int)($_GET['p']??1)));$data['selected']=ArtistClaims::selection($db,$user);}
  if($mode==='calls'){$now=date('Y-m-d H:i:s');$calls=Db::query($db,"SELECT id,title,criteria FROM art_calls WHERE status='published' AND (start_at IS NULL OR start_at='' OR start_at<=?) AND (end_at IS NULL OR end_at='' OR end_at>=?) ORDER BY id DESC",[$now,$now])->fetchAll();$calls=array_values(array_filter($calls,fn($c)=>(Protocol::decode($c['criteria'])['accepting']??true)));$data['result']=['items'=>$calls,'count'=>count($calls)];}
  view('artist-account',$data);
 }
 public static function archiveData(PDO $db):never {
  $user=Security::user($db);if(!$user)throw new HttpError(403,'ورود لازم است.');ArtistMemberships::requireArtist($db,$user);if(strlen($_SERVER['QUERY_STRING']??'')>16000)throw new HttpError(422,'فیلترها بیش از حد هستند.');if(($_GET['mode']??'')==='selection')self::json(['selected'=>ArtistClaims::selection($db,$user)]);$data=GalleryFacets::snapshot($db,$_GET,Security::text($_GET,'changed',30,false));$f=$data['filters'];$base=['section'=>'artist','view'=>'archive'];$data['url']=url('account',$base+$f);
  if(($_GET['mode']??'')==='results'){$f['p']=max(1,(int)($_GET['p']??1));$result=(new Archive($db))->images($f,$f['p']);$selected=ArtistClaims::selection($db,$user);$data['filters']=$f;$data['url']=url('account',$base+$f);ob_start();view('artist-archive-results',compact('db','user','result','selected','f'));$data['html']=ob_get_clean();ob_start();view('martyr-filter-tags',['db'=>$db,'f'=>$f,'filterRoute'=>'account','filterBaseParams'=>$base]);$data['tags']=ob_get_clean();}self::json($data);
 }
 private static function filters(array $f,string $alias='s'):array {
  $where=[];$args=[];foreach(['status'=>'.status','artist_id'=>'.artist_id','martyr_id'=>'.martyr_id'] as $key=>$column)if(($f[$key]??'')!==''){$where[]=($alias==='c'&&$key==='martyr_id')?'EXISTS(SELECT 1 FROM media_public_martyrs pm WHERE pm.image_id=c.image_id AND pm.martyr_id=?)':$alias.$column.'=?';$args[]=Security::text($f,$key,40);}
  foreach(['from'=>'>=','to'=>'<='] as $key=>$op)if(($f[$key]??'')!==''){$v=Security::text($f,$key,10);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v))throw new HttpError(422,'تاریخ فیلتر باید میلادی باشد.');$where[]=$alias.'.created_at'.$op.'?';$args[]=$v.($key==='to'?' 23:59:59':' 00:00:00');}return [$where,$args];
 }
 private static function worksList(PDO $db,array $actor,array $f,bool $own=false,bool $proposals=false):array {
  if(!$own)ArtistMemberships::admin($db,$actor,'artist_works.review');[$where,$args]=self::filters($f);if($own){$where[]='s.user_id=?';$args[]=$actor['id'];}if($proposals)$where[]="r.proposal<>'[]' AND r.proposal<>'{}'";$q=Security::text($f,'q',150,false);if($q!==''){$where[]='(s.title LIKE ? OR a.display_name LIKE ?)';array_push($args,'%'.$q.'%','%'.$q.'%');}
  return AdminQueries::paginate($db,'SELECT s.*,r.martyr_state,r.created_martyr_id,a.display_name AS artist_name','FROM art_submissions s JOIN artist_work_requests r ON r.submission_id=s.id JOIN artists a ON a.id=s.artist_id',implode(' AND ',$where)?:'1=1',$args,['new'=>'s.id DESC'],$f);
 }
 public static function admin(PDO $db,array $user,string $tab,array $data):void {
  ArtistPortalSchema::requireReady($db);$id=(int)($_GET['edit']??0);$data+=['editing'=>null,'history'=>[]];
  if($tab==='artist-joins'){$where=[];$args=[];foreach(['status','user_id'] as $k)if(($_GET[$k]??'')!==''){$where[]='j.'.$k.'=?';$args[]=Security::text($_GET,$k,40);}foreach(['from'=>'>=','to'=>'<='] as $k=>$op)if(($_GET[$k]??'')!==''){$v=Security::text($_GET,$k,10);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v))throw new HttpError(422,'تاریخ معتبر نیست.');$where[]='j.created_at'.$op.'?';$args[]=$v.($k==='to'?' 23:59:59':' 00:00:00');}$q=Security::text($_GET,'q',150,false);if($q!==''){$where[]='j.payload LIKE ?';$args[]='%'.$q.'%';}$data['result']=AdminQueries::paginate($db,'SELECT j.*,u.email','FROM artist_join_requests j JOIN users u ON u.id=j.user_id',implode(' AND ',$where)?:'1=1',$args,['new'=>'j.id DESC'],$_GET);if($id){$data['editing']=Db::query($db,'SELECT j.*,u.email FROM artist_join_requests j JOIN users u ON u.id=j.user_id WHERE j.id=?',[$id])->fetch();$data['history']=CommunityHistory::rows($db,'artist_membership',$id);}}
  elseif($tab==='artist-claims'){[$where,$args]=self::filters($_GET,'c');$q=Security::text($_GET,'q',150,false);if($q!==''){$where[]='(i.title LIKE ? OR a.display_name LIKE ?)';array_push($args,'%'.$q.'%','%'.$q.'%');}$data['result']=AdminQueries::paginate($db,'SELECT c.*,a.display_name AS artist_name,i.title','FROM artist_work_claims c JOIN artists a ON a.id=c.artist_id JOIN images i ON i.id=c.image_id',implode(' AND ',$where)?:'1=1',$args,['new'=>'c.id DESC'],$_GET);$data['newArtists']=Db::query($db,"SELECT a.id,a.display_name FROM artist_join_requests j JOIN artists a ON a.id=j.artist_id WHERE j.status='approved' ORDER BY a.display_name")->fetchAll();if($id)$data['history']=CommunityHistory::rows($db,'artist_work_claim',$id);}
  else {$data['result']=self::worksList($db,$user,$_GET,false,$tab==='artist-martyrs');if($id){$data['editing']=ArtistWorks::get($db,$user,$id);$data['history']=CommunityHistory::rows($db,'art_submission',$id);}}
  if($id&&$tab!=='artist-claims'&&!$data['editing'])throw new HttpError(404,'درخواست پیدا نشد.');view('artist-admin',$data);
 }
 public static function file(PDO $db):never {
  $actor=Security::user($db);if(!$actor)throw new HttpError(404,'فایل پیدا نشد.');ArtistPortalSchema::requireReady($db);$j=Db::query($db,'SELECT * FROM artist_join_requests WHERE id=?',[(int)($_GET['request']??0)])->fetch();if(!$j||((int)$j['user_id']!==(int)$actor['id']&&!Permissions::allows($db,$actor,'artists.membership.review')))throw new HttpError(404,'فایل پیدا نشد.');
  if(($_GET['kind']??'')==='avatar'){$file=Db::query($db,'SELECT * FROM file_assets WHERE id=?',[$j['avatar_asset_id']])->fetch();if(!$file)throw new HttpError(404,'فایل پیدا نشد.');Web::sendFile(Upload::absolute($file['path']),$file['mime'],'inline','avatar.webp');}
  else {$id=(int)($_GET['id']??0);if(!in_array($id,array_map('intval',Protocol::decode($j['payload'])['samples']??[]),true))throw new HttpError(404,'فایل پیدا نشد.');$file=Db::query($db,'SELECT * FROM incoming_assets WHERE id=? AND owner_id=?',[$id,$j['user_id']])->fetch();if(!$file)throw new HttpError(404,'فایل پیدا نشد.');$preview=($_GET['size']??'')!=='original';Web::sendFile(Upload::absolute($file[$preview?'preview_path':'original_path']),$preview?'image/webp':$file['mime'],$preview?'inline':'attachment','sample-'.$id);}
  exit;
 }
}
